function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function dt(ms){if(!ms)return'';try{return new Date(ms).toLocaleString('ar-SA')}catch{return''}}
function renderPlayerSearch(p){const c=$('adminSectionContent');c.innerHTML=`<div class="admin-search-row"><input id="adminPlayerQuery" class="admin-input" placeholder="@اسم_المستخدم أو اسم الشخصية"><button id="adminPlayerSearch" class="admin-action">بحث</button></div><div id="adminPlayerResult">${p?playerCard(p):'<div class="admin-card admin-muted">ابحث عن لاعب لعرض حالته.</div>'}</div>`;$('adminPlayerSearch').onclick=()=>{const q=$('adminPlayerQuery').value.trim();if(q)NativeSocial?.adminSearchPlayer?.(q)};$('adminPlayerQuery').onkeydown=e=>{if(e.key==='Enter')$('adminPlayerSearch').click()};wirePlayerBan()}
function playerCard(p){return `<div class="admin-card" data-admin-player="${esc(p.uid)}"><b>${esc(p.name)} ${p.username?'@'+esc(p.username):''}</b><small>${esc(p.rank||'')} · ${p.banned?'موقوف إداريًا':'الحساب نشط'}</small><div class="admin-card-actions"><button class="admin-action ${p.banned?'good':'danger'}" data-admin-ban="${p.banned?'0':'1'}">${p.banned?'فك الإيقاف':'إيقاف الحساب'}</button></div></div>`}
function wirePlayerBan(){const b=$('adminPlayerResult')?.querySelector('[data-admin-ban]');if(!b)return;b.onclick=()=>{const row=b.closest('[data-admin-player]');NativeSocial?.adminSetPlayerBan?.(row.dataset.adminPlayer,b.dataset.adminBan==='1')}}
