function renderMatches(arr){const c=$('adminSectionContent');if(!arr.length){c.innerHTML='<div class="admin-card admin-muted">لا توجد مباريات نشطة أو منتظرة الآن.</div>';return}c.innerHTML=arr.map(m=>`<div class="admin-card"><b>${m.status==='active'?'مباراة جارية':'انتظار مطابقة'} · ${m.count}/7</b><small>ID: ${esc(m.id)}</small><div class="admin-match-stage">${(m.players||[]).map(p=>`<span>${esc(p.name)} · مرحلة ${p.stage}</span>`).join('')}</div></div>`).join('')}
function renderCase(o){const c=$('adminSectionContent');c.innerHTML=`<div class="admin-card"><div class="admin-case-state"><div><b>${esc(o.title||'التجربة الحالية')}</b><small>6 مراحل محلية</small></div><strong class="${o.enabled?'on':'off'}">${o.enabled?'مفعلة':'موقفة'}</strong></div><div class="admin-card-actions"><button id="adminCaseToggle" class="admin-action ${o.enabled?'danger':'good'}">${o.enabled?'إيقاف التجربة':'تفعيل التجربة'}</button><button id="adminCasePreview" class="admin-action">معاينة</button></div><div class="admin-stage-thumbs">${[1,2,3,4,5,6].map(i=>`<img src="puzzle-${i}.svg" alt="مرحلة ${i}">`).join('')}</div></div>`;$('adminCaseToggle').onclick=()=>NativeSocial?.adminSetCaseEnabled?.(!o.enabled);$('adminCasePreview').onclick=openPreviewDirect}
function renderLogs(arr){const c=$('adminSectionContent');if(!arr.length){c.innerHTML='<div class="admin-card admin-muted">لا توجد إجراءات إدارية مسجلة بعد.</div>';return}const labels={resolve_report:'معالجة بلاغ',ban_player:'إيقاف لاعب',unban_player:'فك إيقاف لاعب',enable_case:'تفعيل التجربة',disable_case:'إيقاف التجربة'};c.innerHTML=arr.map(x=>`<div class="admin-card"><b class="admin-log-action">${labels[x.action]||esc(x.action)}</b><small>${dt(x.time)}${x.target?' · '+esc(x.target):''}</small></div>`).join('')}
