$('settingHelp')?.addEventListener('click',e=>{e.preventDefault();$('helpReportPanel').hidden=false});$('helpReportBack')?.addEventListener('click',()=>$('helpReportPanel').hidden=true);$('reportSend')?.addEventListener('click',()=>{const t=$('reportText').value.trim();if(!t)return $('reportStatus').textContent='اكتب تفاصيل البلاغ أولًا.';$('reportStatus').textContent='جارٍ الإرسال…';NativeSocial?.submitReport?.($('reportType').value,t)});
const prev=window.onNativeSocialResult;window.onNativeSocialResult=r=>{prev?.(r);if(!r)return;if(r.action==='adminDashboard'&&r.ok){$('adminUsersCount').textContent=r.users;$('adminActiveMatches').textContent=r.activeMatches;$('adminWaitingPlayers').textContent=r.waitingPlayers;$('adminOpenReports').textContent=r.openReports}else if(r.action==='adminReports'&&r.ok&&activeAdminSection==='reports')renderReports(r.reports||[]);else if(r.action==='adminPlayer'&&r.ok&&activeAdminSection==='players')renderPlayerSearch(r.player);else if(r.action==='adminPlayerBan'&&r.ok&&activeAdminSection==='players'){const q=$('adminPlayerQuery')?.value;if(q)NativeSocial?.adminSearchPlayer?.(q)}else if(r.action==='adminMatches'&&r.ok&&activeAdminSection==='matches')renderMatches(r.matches||[]);else if(r.action==='adminCase'&&r.ok&&activeAdminSection==='cases')renderCase(r);else if(r.action==='adminLogs'&&r.ok&&activeAdminSection==='logs')renderLogs(r.logs||[]);else if(r.action==='reportSubmitted'&&r.ok){$('reportText').value='';$('reportStatus').textContent='تم إرسال البلاغ إلى الإدارة.'}}
