;(()=>{
const SOCIAL_WORLD_V2=true,$=id=>document.getElementById(id);
const places=[['beach','الشاطئ'],['palace','القصر'],['garden','الحديقة'],['hospital','المستشفى'],['police','مركز الشرطة والسجن'],['market','السوق'],['restaurant','المطعم / المقهى'],['hotel','الفندق'],['harbor','الميناء']];
let preview=false,current='beach',naderPlace='beach',naderTyping=false,returnState=[],keyboardBottom=0,naderSession='',naderStarting=null;
const baseCounts={beach:0,palace:0,garden:0,hospital:0,police:0,market:0,restaurant:0,hotel:0,harbor:0};
const messages={};
const nameOf=k=>(places.find(x=>x[0]===k)||[])[1]||k;
function profileName(){try{const p=JSON.parse(localStorage.getItem('profile_cache')||'{}');return p.name||p.displayName||JSON.parse(localStorage.getItem('investigator_name')||'null')||'أنت'}catch{return'أنت'}}
function ensure(k){if(!messages[k])messages[k]=[]}
function countAt(k){return (preview?0:(baseCounts[k]||0))+(naderPlace===k?1:0)}
function addSystem(k,text){ensure(k);const last=messages[k][messages[k].length-1];if(last?.system&&last.text===text)return;messages[k].push({system:true,text})}
function addMsg(k,name,text,mine=false,nader=false){ensure(k);messages[k].push({name,text,mine,nader})}
function render(){ensure(current);const g=$('worldGame');if(!g)return;g.dataset.place=current;$('worldPlaceName').textContent=nameOf(current);$('worldModeLabel').textContent=preview?'معاينة الإدارة · نفس العالم':'العالم';$('worldPresenceText').textContent='الموجودون الآن · '+countAt(current);const ns=$('worldNaderStatus');if(ns)ns.hidden=naderPlace!==current;const av=$('worldAvatars');av.innerHTML='';if(naderPlace===current){const n=document.createElement('span');n.className='world-avatar nader';n.textContent='ن';n.title='نادر';av.appendChild(n)}if(!preview)for(let i=0;i<Math.min(baseCounts[current]||0,4);i++){const x=document.createElement('span');x.className='world-avatar';x.textContent=String(i+1);av.appendChild(x)}const m=$('worldMessages');m.innerHTML='';messages[current].forEach(x=>{const d=document.createElement('div');if(x.system){d.className='world-system';d.textContent=x.text}else{d.className='world-msg'+(x.mine?' mine':'')+(x.nader?' nader':'');d.innerHTML='<b></b><span></span>';d.querySelector('b').textContent=x.name;d.querySelector('span').textContent=x.text}m.appendChild(d)});const t=$('worldTyping');if(t){t.hidden=!(naderTyping&&naderPlace===current);t.textContent='نادر يكتب…'}requestAnimationFrame(()=>{m.scrollTop=m.scrollHeight});renderPlaces()}
function renderPlaces(){const grid=$('worldPlacesGrid');if(!grid)return;grid.innerHTML='';places.forEach(([k,n])=>{const b=document.createElement('button');b.type='button';b.className='world-place-card'+(k===current?' active':'');b.innerHTML='<strong>'+n+'</strong><small>الموجودون الآن · '+countAt(k)+(naderPlace===k?' · نادر هنا':'')+'</small>';b.onclick=()=>move(k);grid.appendChild(b)})}
function move(k){if(k===current){$('worldPlaces').hidden=true;return}current=k;ensure(k);addSystem(k,'وصلت إلى '+nameOf(k));$('worldPlaces').hidden=true;render();maybeNaderGreets()}
function captureReturnState(){returnState=[];document.querySelectorAll('main').forEach(m=>{if(m.id!=='worldGame'&&!m.hidden&&getComputedStyle(m).display!=='none')returnState.push(m.id)})}
function isolate(){captureReturnState();document.body.classList.add('world-preview-active');document.querySelectorAll('main').forEach(m=>{if(m.id!=='worldGame')m.hidden=true})}
function openWorld(isPreview=false){preview=!!isPreview;current='beach';const g=$('worldGame');if(!g)return;if(!g.hidden){render();return}isolate();g.hidden=false;document.body.style.overflow='hidden';ensure(current);if(!messages[current].length)addSystem(current,'وصلت إلى '+nameOf(current));render();maybeNaderGreets()}
function closeWorld(){const g=$('worldGame');if(g)g.hidden=true;document.body.classList.remove('world-preview-active');document.body.style.overflow='';const saved=[...returnState];returnState=[];let restored=false;saved.forEach(id=>{const e=$(id);if(e){e.hidden=false;restored=true}});if(!restored){if(preview&&$('adminDashboard')){$('adminDashboard').hidden=false}else window.showHQ?.()}}
function worldAiRequest(path,method='POST',body={}){
  if(typeof window.HSNSNAiRequest!=='function')return Promise.reject(new Error('اتصال نادر الحقيقي غير جاهز'));
  return Promise.race([
    window.HSNSNAiRequest(path,method,body),
    new Promise((_,reject)=>setTimeout(()=>reject(new Error('انتهت مهلة اتصال نادر')),35000))
  ]);
}
async function ensureRealNader(){if(naderSession)return naderSession;if(naderStarting)return naderStarting;naderStarting=worldAiRequest('/api/admin/nader/session','POST',{playerName:profileName()}).then(d=>{naderSession=d.sessionId||'';if(!naderSession)throw new Error('لم تبدأ جلسة نادر');if(d.message)addMsg(current,'نادر',d.message,false,true);render();return naderSession}).finally(()=>{naderStarting=null});return naderStarting}
async function naderSpeak(text){if(naderPlace!==current)return;try{await ensureRealNader();const d=await worldAiRequest('/api/admin/nader/chat','POST',{sessionId:naderSession,text});naderTyping=false;if(d.message)addMsg(current,'نادر',d.message,false,true);render()}catch(e){naderTyping=false;addSystem(current,'تعذر اتصال نادر الحقيقي: '+String(e?.message||e));render()}}
async function maybeNaderGreets(){if(naderPlace!==current)return;ensure(current);if(messages[current].some(x=>x.nader))return;try{await ensureRealNader()}catch(e){naderTyping=false;addSystem(current,'تعذر اتصال نادر الحقيقي');render()}}
function moveNader(){const choices=places.map(x=>x[0]).filter(k=>k!==naderPlace);const next=choices[Math.floor(Math.random()*choices.length)];naderPlace=next;render();if(naderPlace===current)maybeNaderGreets()}
setInterval(()=>{if(!$('worldGame')?.hidden&&!preview&&Math.random()<.34)moveNader()},45000);
function fixKeyboard(){const g=$('worldGame');if(!g||g.hidden)return;const vv=window.visualViewport;if(vv){keyboardBottom=Math.max(0,window.innerHeight-vv.height-vv.offsetTop);g.style.paddingBottom=keyboardBottom+'px';setTimeout(()=>{const m=$('worldMessages');if(m)m.scrollTop=m.scrollHeight},60)}}
window.visualViewport?.addEventListener('resize',fixKeyboard);window.visualViewport?.addEventListener('scroll',fixKeyboard);
document.addEventListener('click',e=>{if(e.target.closest?.('#worldBack'))closeWorld();if(e.target.closest?.('#worldPlacesOpen')){$('worldPlaces').hidden=false;renderPlaces()}if(e.target.closest?.('#worldPlacesClose'))$('worldPlaces').hidden=true},true);
$('worldInput')?.addEventListener('focus',()=>setTimeout(fixKeyboard,80));
$('worldComposer')?.addEventListener('submit',e=>{e.preventDefault();const i=$('worldInput'),t=i.value.trim();if(!t)return;ensure(current);addMsg(current,profileName(),t,true,false);i.value='';render();if(naderPlace===current)naderSpeak(t)});
window.HSNSNWorld={open:()=>openWorld(false),preview:()=>openWorld(true),move,close:closeWorld,moveNader};
})();

;(()=>{
const NADER_AI_ADMIN_V1=true,$=id=>document.getElementById(id);
let pending=new Map(),naderSession='';
const serverKey='hsnsn_ai_server_url';
function aiPanel(open){const p=$('adminAiPanel');if(p)p.hidden=!open}
function aiStatus(text,kind=''){const e=$('adminAiStatus');if(!e)return;e.textContent=text;e.className='admin-ai-status'+(kind?' '+kind:'')}
function serverUrl(){return String($('adminAiServer')?.value||'').trim().replace(/\/+$/,'')}
function saveServer(){const v=serverUrl();if(v)localStorage.setItem(serverKey,v)}
function parseBody(raw){try{return JSON.parse(raw||'{}')}catch{return {}}}
function request(path,method='POST',body={}){return new Promise((resolve,reject)=>{const base=serverUrl();if(!base){reject(new Error('ضع عنوان خادم الذكاء الاصطناعي أولاً.'));return}if(!base.startsWith('https://')){reject(new Error('عنوان الخادم يجب أن يبدأ بـ https://'));return}saveServer();const id='ai_'+Date.now()+'_'+Math.random().toString(36).slice(2);pending.set(id,{resolve,reject});try{if(typeof NativeAuth==='undefined'||typeof NativeAuth.adminAiRequest!=='function')throw new Error('نسخة التطبيق لا تدعم اتصال الذكاء الاصطناعي.');NativeAuth.adminAiRequest(id,base,path,method,JSON.stringify(body||{}))}catch(e){pending.delete(id);reject(e)}})}
window.HSNSNAiRequest=(path,method='POST',body={})=>{const el=$('adminAiServer');if(el&&!String(el.value||'').trim()){try{el.value=localStorage.getItem(serverKey)||''}catch{}}return request(path,method,body)};
window.onNativeAdminAiResult=p=>{const q=pending.get(String(p?.requestId||''));if(!q)return;pending.delete(String(p.requestId));const data=parseBody(p.body);if(p.ok)q.resolve(data);else q.reject(new Error(data.error||p.message||('HTTP '+(p.status||0))))};
function busy(btn,on,label){if(!btn)return;if(on){btn.dataset.old=btn.textContent;btn.textContent=label||'جارٍ…';btn.disabled=true}else{btn.textContent=btn.dataset.old||btn.textContent;btn.disabled=false}}
async function refreshStatus(){try{aiStatus('جارٍ فحص إعدادات السيرفر…');const d=await request('/api/admin/ai/status','GET');$('adminAiKey').placeholder=d.configured?'المفتاح محفوظ على السيرفر ••••••••':'sk-••••••••••••••••';aiStatus(d.configured?`المفتاح محفوظ ✓ · النموذج ${d.model||'gpt-5.6-luna'}`:'لم يتم حفظ مفتاح OpenAI بعد.',d.configured?'good':'')}catch(e){aiStatus('تعذر الاتصال: '+e.message,'bad')}}
$('adminAiOpen')?.addEventListener('click',()=>{const v=localStorage.getItem(serverKey)||'';if($('adminAiServer'))$('adminAiServer').value=v;aiPanel(true);if(v)refreshStatus();else aiStatus('ضع عنوان خادم الذكاء الاصطناعي أولاً.','')});
$('adminAiBack')?.addEventListener('click',()=>aiPanel(false));
$('adminAiSave')?.addEventListener('click',async()=>{const b=$('adminAiSave'),key=String($('adminAiKey')?.value||'').trim();if(!key){aiStatus('الصق مفتاح OpenAI أولاً.','bad');return}try{busy(b,true,'جارٍ الحفظ…');await request('/api/admin/ai/key','POST',{apiKey:key});$('adminAiKey').value='';$('adminAiKey').placeholder='المفتاح محفوظ على السيرفر ••••••••';aiStatus('تم حفظ المفتاح كسر مشفر على السيرفر ✓','good')}catch(e){aiStatus('فشل الحفظ: '+e.message,'bad')}finally{busy(b,false)}});
$('adminAiTest')?.addEventListener('click',async()=>{const b=$('adminAiTest');try{busy(b,true,'جارٍ الاختبار…');const d=await request('/api/admin/ai/test','POST',{});aiStatus(`الاتصال ناجح ✓ · ${d.model||'OpenAI'}`,'good')}catch(e){aiStatus('فشل اختبار الاتصال: '+e.message,'bad')}finally{busy(b,false)}});
function addMsg(who,text){const box=$('naderPreviewChat');if(!box)return;box.querySelector('.nader-preview-empty')?.remove();const d=document.createElement('div');d.className='nader-msg '+(who==='me'?'me':'ai');const s=document.createElement('small');s.textContent=who==='me'?'أنت':'نادر';const t=document.createElement('div');t.textContent=text;d.append(s,t);box.appendChild(d);box.scrollTop=box.scrollHeight}
$('naderStart')?.addEventListener('click',async()=>{const b=$('naderStart');try{busy(b,true,'نادر يدخل…');naderSession='';const box=$('naderPreviewChat');if(box)box.innerHTML='<div class="nader-preview-empty">جارٍ بدء الجلسة…</div>';const d=await request('/api/admin/nader/session','POST',{playerName:'الادمن'});naderSession=d.sessionId||'';if(box)box.innerHTML='';addMsg('ai',d.message||'هلا')}catch(e){aiStatus('تعذر بدء جلسة نادر: '+e.message,'bad')}finally{busy(b,false)}});
async function sendNader(){const input=$('naderInput'),b=$('naderSend'),text=String(input?.value||'').trim();if(!text)return;if(!naderSession){aiStatus('ابدأ جلسة نادر أولاً.','bad');return}input.value='';addMsg('me',text);try{busy(b,true,'…');input.disabled=true;const d=await request('/api/admin/nader/chat','POST',{sessionId:naderSession,text});addMsg('ai',d.message||'')}catch(e){addMsg('ai','[تعذر الرد: '+e.message+']')}finally{busy(b,false);input.disabled=false;input.focus()}}
$('naderSend')?.addEventListener('click',sendNader);$('naderInput')?.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendNader()}});
})();

